def db():
    if not DATABASE_URL:
        raise RuntimeError("DATABASE_URL eksik. Supabase PostgreSQL bağlantısını Render Environment bölümüne ekle.")
    return psycopg.connect(DATABASE_URL, row_factory=dict_row, connect_timeout=10)

# Basic Turkish profanity/insult filter. Keep matching word-boundary based to reduce false positives.
PROFANITY_RE = re.compile(
    r"(?i)(?<![\w])(?:"
    r"amk|aq|a\.q|oç|mal/oc|orospu|siktir|sikik|sikerim|sikeyim|sik\w*|"
    r"yarrak|yarr\w*|piç|pic|kahpe|pezevenk|göt|got|bok\w*|"
    r"ananı|ananin|anan\w*|ibne|gerizekalı|gerizekali|"
    r"salak\s+or\w*|mal\s+oğlu\s+mal|fuck\w*|shit|bitch|asshole|motherfucker"
    r")(?![\w])"
)


def normalize_moderation_text(value: str) -> str:
    value = (value or "").casefold().translate(str.maketrans({"ı":"i", "ş":"s", "ğ":"g", "ü":"u", "ö":"o", "ç":"c", "0":"o", "1":"i", "3":"e", "4":"a", "@":"a", "$":"s"}))
    # Collapse punctuation/spacing between letters to catch common obfuscation without storing message contents.
    return re.sub(r"[^a-z]+", "", value)

NORMALIZED_PROFANITY = tuple("amk aq oc orospu siktir sikik sikerim yarrak pic kahpe pezevenk got bok ibne gerizekali fuck shit bitch asshole motherfucker".split())

def contains_profanity(value: str) -> bool:
    value = (value or "").casefold().translate(str.maketrans({"ı":"i", "ş":"s", "ğ":"g", "ü":"u", "ö":"o", "ç":"c", "0":"o", "1":"i", "3":"e", "4":"a", "@":"a", "$":"s"}))
    if PROFANITY_RE.search(value):
        return True
    # Detect common punctuation/space obfuscation while preserving word boundaries.
    for term in NORMALIZED_PROFANITY:
        pattern = r"(?<![a-z])" + r"[^a-z]{0,2}".join(map(re.escape, term)) + r"(?![a-z])"
        if re.search(pattern, value):
            return True
    return False

def client_ip(request: Request) -> str:
    # Do not trust arbitrary X-Forwarded-For input; this is a network address, not a unique device ID.
    return request.client.host if request.client else "unknown"


def active_ip_ban(ip: str):
    if not DATABASE_URL or ip == "unknown":
        return None
    with db() as conn:
        row = conn.execute(
            "SELECT expires_at FROM moderation_bans WHERE ip_address=%s AND expires_at > NOW()",
            (ip,),
        ).fetchone()
        if row:
            return row["expires_at"]
        conn.execute("DELETE FROM moderation_bans WHERE ip_address=%s AND expires_at <= NOW()", (ip,))
    return None

def device_cookie_hash(request: Request) -> str | None:
    token = request.cookies.get("tekden_device_id", "")
    if not token or len(token) < 32 or len(token) > 160:
        return None
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def active_device_ban(request: Request):
    token_hash = device_cookie_hash(request)
    if not DATABASE_URL or not token_hash:
        return None
    with db() as conn:
        row = conn.execute(
            "SELECT expires_at FROM moderation_bans WHERE ip_address=%s AND expires_at>NOW()",
            ("device:" + token_hash,),
        ).fetchone()
        return row["expires_at"] if row else None


def active_user_ban(user_id: int):
    if not DATABASE_URL or not user_id:
        return None
    with db() as conn:
        row = conn.execute("SELECT expires_at FROM moderation_bans WHERE user_id=%s AND expires_at>NOW() ORDER BY expires_at DESC LIMIT 1", (user_id,)).fetchone()
        return row["expires_at"] if row else None


@app.middleware("http")
async def enforce_moderation_ban(request: Request, call_next):
    # Ban checks cover the public site, API, new chats and refreshed sessions.
    exempt = request.url.path in ("/health", "/api/health/db", "/api/health/deep")
    try:
        if not exempt:
            expires = active_ip_ban(client_ip(request))
            if not expires:
                expires = active_device_ban(request)
            if not expires:
                try:
                    session_user = current_user(request)
                    if session_user:
                        expires = active_user_ban(session_user["id"])
                except Exception:
                    expires = None
            if expires:
                return JSONResponse(
                    status_code=403,
                    content={"detail": "Tekden AI kullanım kuralları nedeniyle erişimin 30 gün boyunca engellendi.",
                             "ban_expires_at": expires.isoformat()},
                )
        response = await call_next(request)
        if not request.cookies.get("tekden_device_id"):
            response.set_cookie(
                "tekden_device_id", secrets.token_urlsafe(32), max_age=60*60*24*365,
                httponly=True, secure=request.url.scheme == "https",
                samesite="lax", path="/",
            )
        return response
    except Exception as exc:
        # A database outage must not falsely claim that a moderation ban succeeded.
        print("[Tekden AI] Moderasyon kontrolü:", type(exc).__name__)
        return await call_next(request)


def ban_ip_for_month(ip: str, user_id: int | None = None, request: Request | None = None):
    if not DATABASE_URL or (ip == "unknown" and not user_id and not request):
        raise RuntimeError("Moderasyon veritabanı yapılandırılmamış.")
    with db() as conn:
        if ip != "unknown":
            conn.execute("""
                INSERT INTO moderation_bans(ip_address, user_id, reason, banned_at, expires_at)
                VALUES(%s, %s, 'Hakaret/küfür içeren mesaj', NOW(), NOW() + INTERVAL '30 days')
                ON CONFLICT(ip_address) DO UPDATE SET
                    user_id=COALESCE(EXCLUDED.user_id, moderation_bans.user_id),
                    reason=EXCLUDED.reason, banned_at=NOW(), expires_at=NOW() + INTERVAL '30 days'
            """, (ip, user_id))
        elif user_id:
            conn.execute("""
                INSERT INTO moderation_bans(ip_address, user_id, reason, banned_at, expires_at)
                VALUES('account:' || %s::text, %s, 'Hakaret/küfür içeren mesaj', NOW(), NOW() + INTERVAL '30 days')
                ON CONFLICT(ip_address) DO UPDATE SET user_id=EXCLUDED.user_id, reason=EXCLUDED.reason,
                    banned_at=NOW(), expires_at=NOW() + INTERVAL '30 days'
            """, (user_id, user_id))
        token_hash = device_cookie_hash(request) if request else None
        if token_hash:
            conn.execute("""
                INSERT INTO moderation_bans(ip_address, user_id, reason, banned_at, expires_at)
                VALUES(%s, %s, 'Hakaret/küfür içeren mesaj', NOW(), NOW() + INTERVAL '30 days')
                ON CONFLICT(ip_address) DO UPDATE SET user_id=COALESCE(EXCLUDED.user_id, moderation_bans.user_id),
                    reason=EXCLUDED.reason, banned_at=NOW(), expires_at=NOW() + INTERVAL '30 days'
            """, ("device:" + token_hash, user_id))


def init_db():
    with db() as conn:
        conn.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id BIGSERIAL PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            plan TEXT NOT NULL DEFAULT 'free',
            stripe_customer_id TEXT,
            stripe_subscription_id TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS chats (
            id UUID PRIMARY KEY,
            user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            title TEXT NOT NULL DEFAULT 'Yeni sohbet',
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            archived BOOLEAN NOT NULL DEFAULT FALSE
        )""")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS messages (
            id BIGSERIAL PRIMARY KEY,
            chat_id UUID NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
            role TEXT NOT NULL CHECK (role IN ('user','assistant')),
            content TEXT NOT NULL,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS plan TEXT NOT NULL DEFAULT 'free'")
        conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS stripe_customer_id TEXT")
        conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS stripe_subscription_id TEXT")
        conn.execute("ALTER TABLE chats ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_chats_user_updated ON chats(user_id, archived, updated_at DESC)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_messages_chat_id ON messages(chat_id, id)")
        # IP-based temporary moderation bans. This is a network-level approximation, not a unique device ID.
        conn.execute("""
        CREATE TABLE IF NOT EXISTS moderation_bans (
            id BIGSERIAL PRIMARY KEY,
            ip_address TEXT NOT NULL,
            reason TEXT NOT NULL DEFAULT 'Hakaret/küfür içeren mesaj',
            banned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            expires_at TIMESTAMPTZ NOT NULL,
            UNIQUE(ip_address)
        )""")
        conn.execute("ALTER TABLE moderation_bans ADD COLUMN IF NOT EXISTS user_id BIGINT REFERENCES users(id) ON DELETE CASCADE")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_moderation_bans_expiry ON moderation_bans(expires_at)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_moderation_bans_user ON moderation_bans(user_id, expires_at)")
        # Optional account features are stored separately so older accounts migrate safely.
        conn.execute("""
        CREATE TABLE IF NOT EXISTS user_preferences (
            user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
            display_name TEXT NOT NULL DEFAULT '',
            response_style TEXT NOT NULL DEFAULT 'balanced',
            theme TEXT NOT NULL DEFAULT 'system',
            save_history BOOLEAN NOT NULL DEFAULT TRUE,
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS user_feedback (
            id BIGSERIAL PRIMARY KEY,
            user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
            category TEXT NOT NULL,
            message TEXT NOT NULL,
            page TEXT NOT NULL DEFAULT '',
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_feedback_created ON user_feedback(created_at DESC)")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS saved_prompts (
            id BIGSERIAL PRIMARY KEY,
            user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            title TEXT NOT NULL,
            prompt TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'Genel',
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            UNIQUE(user_id, title)
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_saved_prompts_user ON saved_prompts(user_id, created_at DESC)")
        # Additive productivity features; these tables do not alter existing chat data.
        conn.execute("ALTER TABLE user_preferences ADD COLUMN IF NOT EXISTS custom_instructions TEXT NOT NULL DEFAULT ''")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS user_notes (
            id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            title TEXT NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_user_notes_user_updated ON user_notes(user_id, updated_at DESC)")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS user_bookmarks (
            id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            chat_id UUID REFERENCES chats(id) ON DELETE SET NULL, title TEXT NOT NULL,
            content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_user_bookmarks_user_created ON user_bookmarks(user_id, created_at DESC)")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS response_ratings (
            id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
            rating SMALLINT NOT NULL CHECK (rating IN (-1,1)), context TEXT NOT NULL DEFAULT '',
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS feature_requests (
            id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
            title TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'planned',
            votes INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("""
        CREATE TABLE IF NOT EXISTS feature_request_votes (
            user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            feature_id BIGINT NOT NULL REFERENCES feature_requests(id) ON DELETE CASCADE,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id, feature_id)
        )""")
        # Cross-session project memory is separate from chats and can be edited/deleted by its owner.
        conn.execute("""
        CREATE TABLE IF NOT EXISTS project_memories (
            id BIGSERIAL PRIMARY KEY,
            user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            project_name TEXT NOT NULL,
            summary TEXT NOT NULL DEFAULT '',
            next_actions TEXT NOT NULL DEFAULT '',
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            UNIQUE(user_id, project_name)
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_project_memories_user_updated ON project_memories(user_id, updated_at DESC)")
        # Anonymous opt-in community pulse: store only a coarse topic label, never raw prompts or project content.
        conn.execute("""
        CREATE TABLE IF NOT EXISTS mind_idea_pulses (
            id BIGSERIAL PRIMARY KEY,
            user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
            topic TEXT NOT NULL CHECK (topic IN ('yapay-zeka','yazilim','egitim','tasarim','oyun','robotik','diger')),
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_mind_idea_pulses_topic_date ON mind_idea_pulses(topic, created_at DESC)")
        # User-owned source history. Versions are saved only when the user explicitly submits them.
        conn.execute("""
        CREATE TABLE IF NOT EXISTS mind_code_heritage (
            id BIGSERIAL PRIMARY KEY,
            user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            project_name TEXT NOT NULL,
            version_label TEXT NOT NULL DEFAULT '',
            source_code TEXT NOT NULL,
            source_hash TEXT NOT NULL,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_mind_code_heritage_user_project ON mind_code_heritage(user_id, project_name, created_at DESC)")
        # Anonymous opt-in aggregate: no account id, raw prompt, code, or free-text content is stored.
        conn.execute("""
        CREATE TABLE IF NOT EXISTS mind_success_pulses (
            id BIGSERIAL PRIMARY KEY,
            topic TEXT NOT NULL CHECK (topic IN ('yapay-zeka','yazilim','egitim','tasarim','oyun','robotik','diger')),
            outcome TEXT NOT NULL CHECK (outcome IN ('cozuldu','devam_ediyor','cozulemedi')),
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_mind_success_pulses_topic_date ON mind_success_pulses(topic, created_at DESC)")
        # Controlled background code-evolution jobs. Source snapshots are analyzed, never executed or auto-deployed.
        conn.execute("""
        CREATE TABLE IF NOT EXISTS mind_evolution_jobs (
            id BIGSERIAL PRIMARY KEY,
            user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            project_name TEXT NOT NULL,
            goal TEXT NOT NULL DEFAULT '',
            code_snapshot TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','completed','failed')),
            result TEXT NOT NULL DEFAULT '',
            error TEXT NOT NULL DEFAULT '',
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_mind_evolution_jobs_queue ON mind_evolution_jobs(status, created_at)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_mind_evolution_jobs_user ON mind_evolution_jobs(user_id, created_at DESC)")
        # Recover jobs interrupted by a process restart; current worker calls have a 120-second provider timeout.
        conn.execute("UPDATE mind_evolution_jobs SET status='queued', updated_at=NOW() WHERE status='running' AND updated_at < NOW() - INTERVAL '10 minutes'")
        # Owner account is provisioned from Render environment variables, never from a hard-coded password.
        if OWNER_PASSWORD and len(OWNER_PASSWORD) >= 8 and OWNER_USERNAME:
            owner = conn.execute("SELECT id FROM users WHERE lower(username)=lower(%s)", (OWNER_USERNAME,)).fetchone()
            if owner:
                conn.execute("UPDATE users SET plan='plus', password_hash=%s WHERE id=%s", (hash_password(OWNER_PASSWORD), owner["id"]))
            else:
                conn.execute("INSERT INTO users(username,password_hash,plan) VALUES(%s,%s,'plus')", (OWNER_USERNAME, hash_password(OWNER_PASSWORD)))
        # One additional Pro account and one additional Plus account.
        # These accounts receive plan access only, never owner/admin privileges.
        for extra_username, extra_password, extra_plan in (
            (EXTRA_PRO_USERNAME, EXTRA_PRO_PASSWORD, "pro"),
            (EXTRA_PLUS_USERNAME, EXTRA_PLUS_PASSWORD, "plus"),
        ):
            if extra_username and extra_password and len(extra_password) >= 8:
                extra = conn.execute("SELECT id FROM users WHERE lower(username)=lower(%s)", (extra_username,)).fetchone()
                if extra:
                    conn.execute("UPDATE users SET plan=%s, password_hash=%s WHERE id=%s",
                                 (extra_plan, hash_password(extra_password), extra["id"]))
                else:
                    conn.execute("INSERT INTO users(username,password_hash,plan) VALUES(%s,%s,%s)",
                                 (extra_username, hash_password(extra_password), extra_plan))


