def plan_feature_summary(plan: str) -> dict:
    key = normalize_plan_name(plan)
    source = PLAN_FEATURES[key]
    return {**source, "features": list(source["features"])}

def normalize_plan_name(plan: str | None) -> str:
    value = str(plan or "free").strip().lower()
    return value if value in ("free", "pro", "plus") else "free"

def user_has_pro_access(user: dict | None) -> bool:
    return bool(user and normalize_plan_name(user.get("plan")) in ("pro", "plus"))

def user_has_plus_access(user: dict | None) -> bool:
    if not user:
        return False
    is_configured_owner = bool(
        OWNER_PASSWORD
        and str(user.get("username", "")).strip().lower() == OWNER_USERNAME.lower()
    )
    return normalize_plan_name(user.get("plan")) == "plus" or is_configured_owner

def user_can_generate_custom_game(user: dict | None) -> bool:
    return user_has_pro_access(user)

def safe_game_title(prompt: str, default: str = "Tekden AI oyunu") -> str:
    """Build a short UI title from a user prompt without trusting markup."""
    compact = re.sub(r"\s+", " ", str(prompt or "")).strip()
    return (compact[:56].rstrip() or default)

def game_html_has_basic_runtime(html: str) -> bool:
    """Cheap structural guard for generated HTML; not a security sandbox."""
    if not isinstance(html, str) or len(html) < 700:
        return False
    lower = html.lower()
    return "<html" in lower and "<script" in lower and ("requestanimationframe" in lower or "setinterval" in lower or "addEventListener" in html)

def game_export_filename(title: str) -> str:
    """Return a filesystem-safe filename for downloadable HTML game exports."""
    slug = re.sub(r"[^a-zA-Z0-9_-]+", "-", str(title or "tekden-ai-oyunu")).strip("-_")
    return (slug[:48] or "tekden-ai-oyunu") + ".html"

DB_INIT_ERROR = None

@app.on_event("startup")
def startup():
    """Initialize database tables whenever PostgreSQL is configured.

    Session configuration is independent from database schema setup: a missing
    SESSION_SECRET must not silently prevent tables from being created.
    """
    global DB_INIT_ERROR
    if not DATABASE_URL:
        DB_INIT_ERROR = "DATABASE_URL eksik"
        return
    try:
        init_db()
        DB_INIT_ERROR = None
        start_mind_evolution_worker()
    except Exception as exc:
        # Keep the app available so /api/health/db can explain the setup issue.
        DB_INIT_ERROR = f"{type(exc).__name__}: {str(exc)[:350]}"
        print("[Tekden AI] Veritabanı başlatılamadı:", DB_INIT_ERROR)

def b64e(s: str) -> str:
    return base64.urlsafe_b64encode(s.encode()).decode().rstrip("=")

def b64d(s: str) -> str:
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4)).decode()

def make_session(user_id: int) -> str:
    payload = f"{user_id}:{int(time.time()) + SESSION_DAYS*86400}:{secrets.token_hex(8)}"
    sig = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return b64e(payload + ":" + sig)

def read_session(request: Request):
    token = request.cookies.get(COOKIE_NAME)
    if not token or not SESSION_SECRET or len(SESSION_SECRET) < 32:
        return None
    try:
        raw = b64d(token)
        user_id, expires, nonce, sig = raw.split(":", 3)
        payload = f"{user_id}:{expires}:{nonce}"
        expected = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected) or int(expires) < int(time.time()):
            return None
        return int(user_id)
    except Exception:
        return None

def hash_password(password: str, salt: bytes = None) -> str:
    salt = salt or secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 310000)
    return base64.urlsafe_b64encode(salt + digest).decode()

def verify_password(password: str, stored: str) -> bool:
    try:
        raw = base64.urlsafe_b64decode(stored.encode())
        salt, digest = raw[:16], raw[16:]
        candidate = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 310000)
        return hmac.compare_digest(candidate, digest)
    except Exception:
        return False

def current_user(request: Request):
    uid = read_session(request)
    if not uid:
        return None
    with db() as conn:
        return conn.execute("SELECT id, username, plan FROM users WHERE id=%s", (uid,)).fetchone()

def is_owner_account(user: dict | None) -> bool:
    """Only the provisioned owner account can enter the separate management area."""
    return bool(
        user
        and OWNER_USERNAME
        and OWNER_PASSWORD
        and len(OWNER_PASSWORD) >= 8
        and str(user.get("username", "")).casefold() == OWNER_USERNAME.casefold()
    )


def require_owner(request: Request):
    user = current_user(request)
    if not user:
        raise HTTPException(401, "Yönetim sekmesi için önce Tekden AI sahibi hesabınla giriş yapmalısın.")
    if not is_owner_account(user):
        raise HTTPException(403, "Bu yönetim alanı yalnızca site sahibine açıktır.")
    if not has_site_access(request):
        raise HTTPException(401, "Yönetim paneli için önce yönetici kodunu gir.")
    return user


def make_site_access_token() -> str:
    if not SESSION_SECRET or len(SESSION_SECRET) < 32 or not SITE_ACCESS_PIN:
        raise RuntimeError("SITE_ACCESS_PIN veya SESSION_SECRET yapılandırılmamış.")
    expires = int(time.time()) + SITE_ACCESS_SECONDS
    nonce = secrets.token_urlsafe(18)
    pin_tag = hashlib.sha256(SITE_ACCESS_PIN.encode("utf-8")).hexdigest()[:16]
    payload = f"{expires}:{nonce}:{pin_tag}"
    signature = hmac.new(SESSION_SECRET.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()
    return b64e(payload + ":" + signature)


def has_site_access(request: Request) -> bool:
    token = request.cookies.get(SITE_ACCESS_COOKIE, "")
    if not token or not SITE_ACCESS_PIN or not SESSION_SECRET or len(SESSION_SECRET) < 32:
        return False
    try:
        raw = b64d(token)
        expires, nonce, pin_tag, signature = raw.split(":", 3)
        payload = f"{expires}:{nonce}:{pin_tag}"
        expected = hmac.new(SESSION_SECRET.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()
        current_pin_tag = hashlib.sha256(SITE_ACCESS_PIN.encode("utf-8")).hexdigest()[:16]
        return (
            hmac.compare_digest(signature, expected)
            and hmac.compare_digest(pin_tag, current_pin_tag)
            and int(expires) > int(time.time())
        )
    except Exception:
        return False


def site_pin_throttle_key(request: Request) -> str:
    host = request.client.host if request.client else "unknown"
    agent = request.headers.get("user-agent", "")[:160]
    return hashlib.sha256((host + "|" + agent).encode("utf-8", "ignore")).hexdigest()


@app.middleware("http")
async def enforce_site_access(request: Request, call_next):
    """The public site is open; the PIN is checked only on owner management routes."""
    return await call_next(request)


def web_search(query: str):
    """Search the web with deeper results and a resilient fallback chain."""
    query = query.strip()
    if not query:
        return []
    if TAVILY_API_KEY:
        try:
            r = requests.post(
                "https://api.tavily.com/search",
                json={"api_key": TAVILY_API_KEY, "query": query, "search_depth": "advanced",
                      "max_results": 8, "include_answer": False, "include_raw_content": False,
                      "topic": "general"},
                timeout=25,
            )
            r.raise_for_status()
            data = r.json()
            results = []
            for x in data.get("results", []):
                url = x.get("url", "")
                if url.startswith("http"):
                    results.append({"title": x.get("title", "Untitled source"), "url": url,
                                    "snippet": x.get("content", ""), "score": x.get("score")})
            if results:
                return results[:8]
        except Exception:
            pass
    try:
        from ddgs import DDGS
        with DDGS() as ddgs:
            raw = list(ddgs.text(query, max_results=8, safesearch="moderate"))
        results = []
        for x in raw:
            url = x.get("href", x.get("url", ""))
            if url.startswith("http"):
                results.append({"title": x.get("title", "Untitled source"), "url": url,
                                "snippet": x.get("body", x.get("snippet", ""))})
        if results:
            return results[:8]
    except Exception:
        pass
    try:
        from html.parser import HTMLParser
        from urllib.parse import urlparse, parse_qs, unquote
        class DDGParser(HTMLParser):
            def __init__(self):
                super().__init__(); self.items=[]; self.current=None; self.capture=None
            def handle_starttag(self, tag, attrs):
                a=dict(attrs); cls=a.get("class", "")
                if tag == "a" and "result__a" in cls:
                    self.current={"title":"", "url":a.get("href", ""), "snippet":""}; self.capture="title"
                elif self.current is not None and tag in ("a", "div") and "result__snippet" in cls:
                    self.capture="snippet"
            def handle_data(self, data):
                if self.current is not None and self.capture in ("title", "snippet"):
                    self.current[self.capture] += data
            def handle_endtag(self, tag):
                if self.current is not None and tag == "a" and self.capture == "title":
                    self.items.append(self.current); self.current=None; self.capture=None
                elif self.current is not None and self.capture == "snippet" and tag == "div":
                    self.capture=None
        response=requests.get("https://html.duckduckgo.com/html/", params={"q":query},
                              headers={"User-Agent":"Mozilla/5.0 (compatible; TekdenAI/1.0)"}, timeout=18)
        response.raise_for_status(); parser=DDGParser(); parser.feed(response.text)
        cleaned=[]
        for item in parser.items:
            url=item.get("url", "")
            if "duckduckgo.com/l/?" in url:
                url=unquote(parse_qs(urlparse(url).query).get("uddg", [url])[0])
            if url.startswith("http") and item.get("title"):
                cleaned.append({"title":item["title"].strip(), "url":url,
                                "snippet":item.get("snippet", "").strip()})
            if len(cleaned)>=8: break
        if cleaned:
            return cleaned
    except Exception:
        pass
    # Last-resort HTML search fallback; no extra Python package or API key required.
    try:
        from html.parser import HTMLParser
        class BingParser(HTMLParser):
            def __init__(self):
                super().__init__(); self.items=[]; self.in_result=False; self.capture=None; self.current=None
            def handle_starttag(self, tag, attrs):
                a=dict(attrs); cls=a.get("class","")
                if tag=="li" and "b_algo" in cls:
                    self.in_result=True; self.current={"title":"","url":"","snippet":""}
                elif self.in_result and tag=="h2":
                    self.capture="title"
                elif self.in_result and tag=="a" and self.capture=="title" and not self.current["url"]:
                    self.current["url"]=a.get("href","")
                elif self.in_result and tag=="p":
                    self.capture="snippet"
            def handle_data(self,data):
                if self.in_result and self.current is not None and self.capture in ("title","snippet"):
                    self.current[self.capture]+=data
            def handle_endtag(self,tag):
                if self.in_result and tag=="li":
                    if self.current and self.current["url"].startswith("http") and self.current["title"].strip():
                        self.items.append(self.current)
                    self.current=None; self.in_result=False; self.capture=None
                elif tag=="h2": self.capture=None
                elif tag=="p": self.capture=None
        response=requests.get("https://www.bing.com/search",params={"q":query,"count":8},
                              headers={"User-Agent":"Mozilla/5.0 (compatible; TekdenAI/1.0)"},timeout=18)
        response.raise_for_status(); parser=BingParser(); parser.feed(response.text)
        return [{"title":x["title"].strip(),"url":x["url"],"snippet":x["snippet"].strip()}
                for x in parser.items[:8]]
    except Exception:
        return []

def pro_web_search(query: str):
    """Broader Pro research: search several complementary query angles and deduplicate sources."""
    queries = [query.strip(), query.strip() + " official documentation primary sources", query.strip() + " recent analysis data"]
    combined, seen = [], set()
    for q in queries:
        for item in web_search(q):
            url = item.get("url", "")
            if url and url not in seen:
                seen.add(url)
                combined.append(item)
            if len(combined) >= 18:
                return combined
    return combined

def should_search(text: str) -> bool:
    """Search automatically for fresh, verifiable or niche facts; avoid searching every basic concept question."""
    t = re.sub(r"\s+", " ", str(text or "").strip().lower())
    if not t:
        return False
    if any(x in t for x in ("internete bakma", "web'de arama yapma", "webde arama yapma", "arama yapma", "kaynak kullanma")):
        return False
    if t.startswith("/search "):
        return True
    explicit = (
        "internette ara", "web'de ara", "webde ara", "web ara", "web araması", "internetten bul",
        "kaynak göster", "kaynakları göster", "kaynaklarla cevapla", "kaynaklarla araştır",
        "araştır", "derin araştır", "detaylı araştır", "güncel bilgi", "güncel veriler",
        "doğrula", "teyit et", "bul ve listele",
        "search the web", "look up", "latest", "current", "today", "breaking news"
    )
    if any(x in t for x in explicit):
        return True
    time_sensitive = (
        "bugün", "şu an", "şimdi", "son dakika", "en son", "en yeni", "en güncel", "yeni model", "son model", "son gelişme", "güncel", "bu hafta", "bu ay",
        "2025", "2026", "2027", "2028", "2029", "fiyatı", "ücreti", "kaç tl", "ne kadar",
        "kampanya", "stokta", "satışta mı", "sürümü çıktı", "yayımlandı mı", "çıkış tarihi",
        "hava durumu", "hava nasıl", "maç sonucu", "fikstür", "puan durumu", "seçim sonucu",
        "cumhurbaşkanı", "bakan", "yönetmelik", "mevzuat", "yasa değişti", "açık mı", "çalışma saatleri",
        "uçuş", "sefer", "rezervasyon", "etkinlik takvimi", "borsa", "döviz kuru", "faiz oranı"
    )
    if any(x in t for x in time_sensitive):
        return True
    # Current facts about named people, companies, products, services or releases usually need verification.
    if re.search(r"\b(kimdir|kim şu anda|ceo'su kim|sahibi kim|nerede bulunuyor|hangi şirkette)\b", t):
        return True
    if re.search(r"\b(versiyon|sürüm|güncelleme|destekleniyor mu|kapatıldı mı|yasaklandı mı|erişim engeli)\b", t):
        return True
    # Scientific papers, statistics and formal reports are source-sensitive even if not explicitly called research.
    if any(x in t for x in ("istatistik", "bilimsel çalışma", "araştırma makalesi", "akademik kaynak", "resmî açıklama", "rapor verisi")):
        return True
    return False

def call_ollama(messages, model=None):
    if not OLLAMA_API_KEY:
        raise RuntimeError("OLLAMA_API_KEY eksik. Render Environment bölümüne Ollama Cloud API anahtarını ekle.")
    r = requests.post("https://ollama.com/api/chat",
        headers={"Authorization": f"Bearer {OLLAMA_API_KEY}", "Content-Type": "application/json"},
        json={"model": model or OLLAMA_MODEL, "messages": messages, "stream": False},
        timeout=120)
    if not r.ok:
        raise RuntimeError(f"Ollama API hatası ({r.status_code}): {r.text[:500]}")
    data = r.json()
    return data.get("message", {}).get("content") or data.get("response") or "Yanıt alınamadı."

