@app.middleware("http")
async def td_plus_workspace_discovery_link(request: Request, call_next):
    response = await call_next(request)
    if request.url.path != "/" or response.status_code != 200:
        return response
    content_type = response.headers.get("content-type", "")
    body = getattr(response, "body", None)
    if body is None or "text/html" not in content_type:
        return response
    script = r"""<script id="td-plus-workspace-discovery">
(async()=>{try{const r=await fetch('/api/me',{credentials:'same-origin'});if(!r.ok)return;const d=await r.json();if(!d.user||String(d.user.plan||'').trim().toLowerCase()!=='plus')return;
const style='display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:8px 11px;border:1px solid #b9d8fa;border-radius:11px;background:#eff7ff;color:#155db1;text-decoration:none;font:700 12px system-ui;';
const menu=document.getElementById('mobileToolsMenu');if(menu&&!document.getElementById('tdPlusWorkspaceMenuLink')&&!document.getElementById('plusWorkspaceMobileBtn')){const a=document.createElement('a');a.id='tdPlusWorkspaceMenuLink';a.href='/plus-workspace';a.textContent='✦ Plus Çalışma Alanı';a.style.cssText=style+'width:100%;margin-top:7px;';menu.appendChild(a);}
const top=document.querySelector('.top');if(top&&!document.getElementById('tdPlusWorkspaceTopLink')){const a=document.createElement('a');a.id='tdPlusWorkspaceTopLink';a.href='/plus-workspace';a.textContent='✦ Plus Workspace';a.style.cssText=style+'margin-left:8px;white-space:nowrap;';top.appendChild(a);}
}catch(e){}})();
</script>"""
    body = body.replace(b"</body>", script.encode("utf-8") + b"</body>", 1)
    headers = dict(response.headers)
    headers.pop("content-length", None)
    headers.pop("content-encoding", None)
    headers.pop("etag", None)
    return Response(content=body, status_code=response.status_code, headers=headers)




# =============================================================================
# TEKDEN AI — CHAT SEND COMPATIBILITY AND INFRASTRUCTURE DISCLOSURE (ADDITIVE)
# Existing routes, features, and source lines above are retained.
# =============================================================================

# Keep the chat handler reachable to the already-installed browser reliability
# layer even in browsers that do not expose a classic-script function on Window.
# The browser patch above now falls back to the global `send` binding directly.

_TD_BASE_CALL_OLLAMA = call_ollama

def call_ollama(messages, model=None):
    """Preserve the configured model call and add a truthful product-identity rule."""
    prepared_messages = [dict(item) for item in (messages or [])]
    infrastructure_rule = (
        "TEKDEN AI ALTYAPI SORULARI İÇİN ÜRÜN YANITI:\\n"
        "Tekden AI'ın kendi uygulama ve backend sunucu altyapısı vardır; kullanıcı "
        "mesajları önce bu Tekden AI altyapısına ulaşır. Yanıt üretiminde bulut "
        "tabanlı model altyapısı kullanılır. Sağlayıcı ve mimari ayrıntılar "
        "kamuya açıklanmaz. Kullanıcı GPT, Cloud veya hangi sağlayıcıya bağlı "
        "olduğunu sorarsa Tekden AI'ın kendi uygulama sunucusu olduğunu ve "
        "yanıt üretiminde bulut tabanlı model altyapısı kullanıldığını açıkça "
        "belirt; modelin tamamen Tekden AI sunucularında çalıştığını veya "
        "hiçbir harici servis kullanılmadığını iddia etme. Daha fazla ayrıntı "
        "isterse şu kısa yanıtı ver: 'Üzgünüz, altyapımızın daha fazla teknik "
        "ayrıntısı gizlidir.' "
        "Yanıtı kısa ve doğal tut."
    )
    if prepared_messages and prepared_messages[0].get("role") == "system":
        prepared_messages[0]["content"] = (
            str(prepared_messages[0].get("content") or "")
            + "\\n\\n"
            + infrastructure_rule
        )
    else:
        prepared_messages.insert(0, {"role": "system", "content": infrastructure_rule})
    return _TD_BASE_CALL_OLLAMA(prepared_messages, model=model)


# =============================================================================
# TEKDEN AI V7 — SESSION UX AND EXTRA PLAN ACCOUNT SETUP NOTES (APPEND-ONLY)
# Existing V6 routes, capabilities, tables, and account provisioning are kept.
# =============================================================================
# Fast sign-out is handled optimistically in the homepage JavaScript above:
# the UI signs out immediately while /api/logout clears the HttpOnly cookie
# asynchronously. Initial profile rendering no longer waits for chat-history
# retrieval; history is loaded in the background after the account is rendered.
#
# Extra plan accounts are already securely provisioned by init_db() using
# PBKDF2 password hashes and these Render Environment variables:
#   EXTRA_PLUS_USERNAME
#   EXTRA_PLUS_PASSWORD
#   EXTRA_PRO_USERNAME
#   EXTRA_PRO_PASSWORD
# Do not hard-code account passwords in source control. Set the values in
# Render -> Service -> Environment, then deploy/restart once. Existing accounts
# with the same usernames are updated to the configured plan and password.


# =============================================================================
# TEKDEN AI V8 — DATABASE/CHAT DIAGNOSTICS (ADDITIVE)
# =============================================================================
@app.get("/api/health/chat")
def chat_health():
    """Safe operational check; never returns credentials, hostnames or message data."""
    result = {
        "ok": False,
        "database_configured": bool(DATABASE_URL),
        "model_key_configured": bool(OLLAMA_API_KEY),
        "database": "not_configured",
        "required_tables": {},
    }
    if not DATABASE_URL:
        result["reason"] = "DATABASE_URL eksik"
        return result
    try:
        with db() as conn:
            conn.execute("SELECT 1").fetchone()
            result["database"] = "connected"
            for table in ("users", "chats", "messages"):
                found = conn.execute(
                    "SELECT to_regclass(%s) AS name",
                    ("public." + table,),
                ).fetchone()
                result["required_tables"][table] = bool(found and found.get("name"))
        result["ok"] = bool(OLLAMA_API_KEY and all(result["required_tables"].values()))
        if not OLLAMA_API_KEY:
            result["reason"] = "OLLAMA_API_KEY eksik"
        elif not all(result["required_tables"].values()):
            result["reason"] = "Gerekli sohbet tablolarından biri eksik"
        else:
            result["reason"] = "Veritabanı ve temel sohbet yapılandırması hazır"
    except Exception as exc:
        result["database"] = "connection_error"
        result["reason"] = type(exc).__name__
        print("[Tekden AI] Sohbet sağlık kontrolü başarısız:", type(exc).__name__)
    return result

# =============================================================================
# TEKDEN AI V9 — CHAT API ERROR REPORTING (ADDITIVE, NO EXISTING FEATURES REMOVED)
# Convert unexpected /api/chat failures into safe JSON so the browser can show
# a useful explanation instead of the generic "İstek başarısız oldu" message.
# No credentials, infrastructure addresses, SQL, or private message content are
# returned to the browser.
# =============================================================================
@app.middleware("http")
async def td_chat_safe_json_errors(request: Request, call_next):
    try:
        return await call_next(request)
    except Exception as exc:
        if request.url.path != "/api/chat" or request.method != "POST":
            raise

        error_code = secrets.token_hex(3).upper()
        # Check the outer exception first. Starlette/AnyIO may attach an
        # EndOfStream as __cause__ while preserving the real endpoint error
        # (for example RuntimeError) as the raised exception itself.
        candidates = [exc]
        seen = set()
        matched_exc = exc
        while candidates:
            candidate = candidates.pop(0)
            if id(candidate) in seen:
                continue
            seen.add(id(candidate))
            if isinstance(candidate, (requests.Timeout, psycopg.Error, requests.RequestException, RuntimeError)):
                matched_exc = candidate
                break
            for linked in (getattr(candidate, "__context__", None), getattr(candidate, "__cause__", None)):
                if linked is not None and id(linked) not in seen:
                    candidates.append(linked)
            for nested in getattr(candidate, "exceptions", ()):
                if nested is not None and id(nested) not in seen:
                    candidates.append(nested)

        status_code = 500
        if isinstance(matched_exc, requests.Timeout):
            status_code = 504
            detail = "Yanıt servisi zamanında yanıt vermedi. Biraz sonra yeniden dene."
        elif isinstance(matched_exc, psycopg.Error):
            status_code = 503
            detail = "Sohbet veritabanına erişilemedi. Bağlantı ve tablo durumunu kontrol etmek gerekiyor."
        elif isinstance(matched_exc, requests.RequestException):
            status_code = 502
            detail = "Yanıt servisine ulaşılamadı. Sunucu bağlantısını kontrol edip yeniden dene."
        elif isinstance(matched_exc, TDModelCallError):
            status_code = int(matched_exc.status_code or 502)
            category = str(matched_exc.category or "upstream_error")
            if status_code == 402:
                detail = (
                    "Yanıt modeli mevcut plan kapsamında kullanılamıyor veya ek kullanım hakkı gerekiyor. "
                    "Temel model de yanıt veremedi. Model erişim ve kullanım durumunu kontrol et."
                )
            elif status_code in (401, 403):
                status_code = 503
                detail = "Yanıt servisinin erişim ayarlarında sorun var. Sunucu erişim ayarları kontrol edilmeli."
            elif status_code == 429:
                status_code = 503
                detail = "Yanıt servisi kullanım sınırına ulaştı. Biraz sonra tekrar dene."
            elif status_code in (408, 504):
                status_code = 504
                detail = "Yanıt servisi zamanında yanıt vermedi. Tekrar deneyebilirsin."
            elif status_code in (400, 404, 422):
                status_code = 503
                detail = "Yapılandırılmış model bu isteği kabul etmedi. Model ayarları kontrol edilmeli."
            elif status_code in (500, 502, 503):
                detail = "Yanıt sağlayıcısı geçici bir hata döndürdü. Biraz sonra tekrar dene."
            else:
                status_code = 502
                detail = "Yanıt sağlayıcısından geçerli bir sonuç alınamadı."
            print(
                "[Tekden AI] /api/chat sağlayıcı tanısı:",
                status_code,
                category,
            )
        elif isinstance(matched_exc, RuntimeError):
            message = str(matched_exc).lower()
            if "429" in message:
                status_code = 503
                detail = "Yanıt servisi şu anda kullanım sınırına ulaştı. Biraz sonra yeniden dene."
            elif "401" in message or "403" in message:
                status_code = 503
                detail = "Yanıt servisinin erişim ayarlarında sorun var. Sunucu ayarları kontrol edilmeli."
            elif "ollama_api_key" in message:
                status_code = 503
                detail = "Yanıt servisi henüz yapılandırılmamış. Sunucu ayarları kontrol edilmeli."
            elif "504" in message or "timeout" in message or "timed_out" in message:
                status_code = 504
                detail = "Yanıt servisi zamanında yanıt vermedi. İstek süresi sınırlandırıldı; tekrar deneyebilirsin."
            elif "503" in message:
                status_code = 503
                detail = "Yanıt servisi geçici olarak kullanılamıyor. Biraz sonra tekrar dene."
            elif "404" in message or "400" in message or "422" in message:
                status_code = 503
                detail = "Yapılandırılmış model bu isteği kabul etmedi. Model ayarları kontrol edilmeli."
            else:
                status_code = 502
                detail = "Yanıt servisi geçerli bir yanıt oluşturamadı. Biraz sonra yeniden dene."
        else:
            detail = (
                "Sohbet sırasında beklenmeyen bir sunucu hatası oluştu. "
                f"Destek kodu: {error_code}."
            )

        print(
            "[Tekden AI] /api/chat güvenli hata yanıtı:",
            error_code,
            type(matched_exc).__name__,
        )
        return JSONResponse(
            status_code=status_code,
            content={
                "detail": detail,
                "error_code": error_code,
                "endpoint": "chat",
            },
            headers={"Cache-Control": "no-store"},
        )


